package main
import("bytes";"compress/zlib";"encoding/json";"fmt";"io/fs";"os";"path/filepath";"time")
type file struct { Data []byte; Cost int }
func main(){
 b,_:=os.ReadFile("/tmp/drvgo-compression-source-paths.json"); var paths []string; if err:=json.Unmarshal(b,&paths);err!=nil{panic(err)}
 var snapshots [][]file
 for _,p:=range paths { var files []file; cost:=0; err:=filepath.WalkDir(p,func(path string,d fs.DirEntry,err error)error{if err!=nil{return err};if d.IsDir(){return nil};s,err:=d.Info();if err!=nil{return err};rel,err:=filepath.Rel(p,path);if err!=nil{return err};meta:=len(rel)+64;cost+=int(s.Size())+meta;if cost>65536{return fs.SkipAll};data,err:=os.ReadFile(path);files=append(files,file{data,meta});return err});if err!=nil{panic(err)};if cost<=65536{snapshots=append(snapshots,files)}}
 type record struct{Level,Trial,Selected,Bytes int;Seconds float64};var records []record
 for trial:=0;trial<6;trial++ { levels:=[]int{1,3,6};if trial%2==1 {levels=[]int{6,3,1}};for _,level:=range levels{var buf bytes.Buffer;w,err:=zlib.NewWriterLevel(&buf,level);if err!=nil{panic(err)};start:=time.Now();n,total:=0,0;for _,files:=range snapshots{cost:=0;for _,f:=range files{buf.Reset();w.Reset(&buf);w.Write(f.Data);w.Close();size:=len(f.Data);if buf.Len()<size{size=buf.Len()};cost+=size+f.Cost};if cost<=16384 {n++;total+=cost}};r:=record{level,trial,n,total,time.Since(start).Seconds()};records=append(records,r);fmt.Println(r)}}
 data,_:=json.MarshalIndent(records,"","  ");os.WriteFile("/tmp/drvgo-compression-levels.json",data,0644)
}
